<script setup>
import CoverRange from './CoverRange.vue';import CoverColor from './CoverColor.vue';
const props=defineProps({modelValue:Object});const emit=defineEmits(['update:modelValue']);
function set(path,value){const next=JSON.parse(JSON.stringify(props.modelValue)),keys=path.split('.');let target=next;for(const key of keys.slice(0,-1))target=target[key];target[keys.at(-1)]=value;if(path==='gradient'&&!value){delete next.fillLinearGradientColorStops;delete next.fillLinearGradientStartPoint;delete next.fillLinearGradientEndPoint;}if(path.startsWith('gradient')&&path!=='gradient'){delete next.fillLinearGradientColorStops;delete next.fillLinearGradientStartPoint;delete next.fillLinearGradientEndPoint;}emit('update:modelValue',next);}
function reverse(){const next=JSON.parse(JSON.stringify(props.modelValue));delete next.fillLinearGradientColorStops;delete next.fillLinearGradientStartPoint;delete next.fillLinearGradientEndPoint;[next.gradientStartColor,next.gradientColor]=[next.gradientColor,next.gradientStartColor];[next.gradientStartOpacity,next.gradientOpacity]=[next.gradientOpacity,next.gradientStartOpacity];emit('update:modelValue',next);}
</script>
<template><div class="cover-mask-properties"><label class="cover-switch"><input type="checkbox" aria-label="启用遮罩" :checked="modelValue.enabled" @change="set('enabled',$event.target.checked)"/><span>启用遮罩</span></label><div v-if="modelValue.enabled" class="cover-property-card"><div class="cover-property-grid"><CoverColor label="遮罩颜色" :model-value="modelValue.color" @update:model-value="set('color',$event)"/><CoverRange label="遮罩圆角" :model-value="modelValue.radius" :max="300" @update:model-value="set('radius',$event)"/></div><CoverRange label="遮罩透明度" :model-value="Math.round(modelValue.opacity*100)" :max="100" suffix="%" @update:model-value="set('opacity',$event/100)"/>
<label class="cover-switch"><input type="checkbox" aria-label="渐变填充" :checked="modelValue.gradient||!!modelValue.fillLinearGradientColorStops" @change="set('gradient',$event.target.checked)"/><span>渐变填充</span></label><div v-if="modelValue.gradient||modelValue.fillLinearGradientColorStops" class="cover-gradient-properties"><div class="cover-gradient-directions" role="group" aria-label="渐变方向"><span>方向预设</span><button v-for="[angle,label,icon] in [[90,'向下','↓'],[270,'向上','↑'],[0,'向右','→'],[180,'向左','←']]" :key="angle" :aria-label="'渐变'+label" :aria-pressed="modelValue.gradientAngle===angle" @click="set('gradientAngle',angle)">{{icon}}</button><button @click="reverse">反转</button></div><div class="cover-property-grid"><CoverColor label="渐变起点颜色" :model-value="modelValue.gradientStartColor" @update:model-value="set('gradientStartColor',$event)"/><CoverRange label="渐变起点不透明度" :model-value="Math.round(modelValue.gradientStartOpacity*100)" :max="100" suffix="%" @update:model-value="set('gradientStartOpacity',$event/100)"/><CoverColor label="渐变末端颜色" :model-value="modelValue.gradientColor" @update:model-value="set('gradientColor',$event)"/><CoverRange label="渐变末端不透明度" :model-value="Math.round(modelValue.gradientOpacity*100)" :max="100" suffix="%" @update:model-value="set('gradientOpacity',$event/100)"/></div></div>
<label class="cover-switch"><input type="checkbox" aria-label="遮罩描边" :checked="modelValue.stroke.enabled" @change="set('stroke.enabled',$event.target.checked)"/><span>描边</span></label><div v-if="modelValue.stroke.enabled" class="cover-property-grid"><CoverColor label="遮罩描边颜色" :model-value="modelValue.stroke.color" @update:model-value="set('stroke.color',$event)"/><CoverRange label="遮罩描边粗细" :model-value="modelValue.stroke.width" :max="40" @update:model-value="set('stroke.width',$event)"/></div>
<div class="cover-property-grid cover-mask-position"><label v-for="[key,label,min,max] in [['x','遮罩 X',-1080,1080],['y','遮罩 Y',-1920,1920],['width','遮罩宽度',1,2160],['height','遮罩高度',1,3840]]" :key="key">{{label}}<input type="number" :aria-label="label" :value="modelValue[key]" :min="min" :max="max" @change="$event.target.value!==''&&set(key,Math.max(min,Math.min(max,Number($event.target.value))))"/></label></div></div></div></template>
